INSERT INTO `beritas` VALUES (1,'img-berita//687079de1f328.jpg','377 Kepala Keluarga Kampung Kadun Jaya Terima BLT Dana Desa Tahap Akhir Tahun 2021','Timika, fajarpapua.com ΓÇô Pemerintah Kampung Kadun Jaya, Distrik Mimika Timur menyalurkan Bantuan Lan...','377-kepala-keluarga-kampung-kadun-jaya-terima-blt-dana-desa-tahap-akhir-tahun-2021',1,'<p><strong>Timika, fajarpapua.com</strong> ΓÇô Pemerintah Kampung Kadun Jaya, Distrik Mimika Timur menyalurkan Bantuan Langsung Tunai (BLT) Dana Desa tahap akhir Tahun 2021.</p><p>BLT yang bersumber dari dana desa Kampung Kadun Jaya tersebut disalurkan kepada 377 kepala keluarga dengan besaran Rp 900 ribu per triwulan.</p><p>Kepala Kampung Kadun Jaya, Elias Yawa saat ditemui fajarpapua.com, Kamis (23/12) mengatakan pihaknya telah melakukan pembaruan data terkait penerima BLT.</p><p>Diakuinya, sebelumnya terdapat beberapa warga yang berstatus pegawai negeri sipil (PNS,) yang ikut menerima bantuan tersebut.</p><p>ΓÇ£Dari 377 KK itu kan sebelumnya ada PNS yang ikut terima, sehingga kami lakukan pembaruan data dan penerima yang berstatus PNS kami gantikan dengan warga lainnya,ΓÇ¥ ujarnya.</p><p>Besaran dana BLT yang telah dicairkan disalurkan oleh Pemerintah Kampung Kadun Jaya sebesar Rp 339.300.000 atau per kepala keluarga menerima Rp 900 ribu per tiga bulan.</p><p>ΓÇ£377 KK penerima BLT tersebar di 12 RT yang ada di Kampung Kadun Jaya, sehingga terjadi pemerataan dan dari data, para penerima sesuai standar terkait dengan kemampuan ekonominya,ΓÇ¥ tutupnya. (feb)</p><p>&nbsp;</p><p>Sumber : <a href=\"https://fajarpapua.com/2021/12/23/377-kepala-keluarga-kampung-kadun-jaya-terima-blt-dana-desa-tahap-akhir-tahun-2021/\">https://fajarpapua.com/2021/12/23/377-kepala-keluarga-kampung-kadun-jaya-terima-blt-dana-desa-tahap-akhir-tahun-2021/</a></p>',1,2,6,'2024-02-11 06:05:00','2025-08-21 22:56:30'),(2,'img-berita//6870798c785f2.jpg','Cegah Kecurangan PSU Pilkada Mimika, 328 Surat Suara Sisa TPS 01 Kadun Jaya Dimusnahkan, Banyak Pramuria Kilo 10 Ikut Coblos','Timika, fajarpapua.com ΓÇô Pemungutan Suara Ulang (PSU) Pilkada Mimika 2024 di TPS 01, Kampung Kadun J...','cegah-kecurangan-psu-pilkada-mimika-328-surat-suara-sisa-tps-01-kadun-jaya-dimusnahkan-banyak-pramuria-kilo-10-ikut-coblos',1,'<p><strong>Timika, fajarpapua.com</strong> ΓÇô Pemungutan Suara Ulang (PSU) Pilkada Mimika 2024 di TPS 01, Kampung Kadun Jaya, Distrik Wania, Kabupaten Mimika, Provinsi Papua Tengah, Sabtu (7/12/2024) berjalan lancar.</p><p>Nampak masyarakat setempat menggunakan hak pilih sesuai Daftar Pemilih Tetap (DPT) di TPS tersebut.</p><p>TPS 01 Kampung Kadun Jaya memiliki 484 DPT tetapi yang melakukan pencoblosan hanya 169 orang karena sisanya telah pindah penduduk bahkan berdomisili di tempat lain.</p><p>Adapun surat suara cadangan di TPS 01 Kadun Jaya sebanyak 13 ditambah sisa suara 315 dimusnahkan sesuai kesepakatan bersama.</p><p>Total suara sisa dimusnahkan pada TPS 01, Kampung Kadun Jaya sebanyak 328 dengan cara dicoret menggunakan spidol.</p><p>Pemusnahan surat suara sisa ini guna mencegah kecurangan yang masif terjadi selama pelaksanaan Pilkada 2024 di Mimika.</p><p>Nampak masyarakat dan saksi dari masing-masing pasangan calon bupati dan wakil bupati Mimika, calon Gubenur dan Cawagub Papua Tengah menyaksikan pemusnahan surat suara sisa tersebut.</p><p>Berdasarkan informasi dihimpun dari masyarakat yang berdomisili di Kadun Jaya bahwa sebenarnya jumlah DPT di TPS itu tidak sampai 484.</p><p>DPT di TPS 01 Kampung Kadun Jaya hanya sekitar 200 lebih karena banyak yang telah pindah domisili. Proses perhitungan perolehan suara di TPS itu akan dilakukan pada pukul 14:00 WIT.</p><p>Menariknya, banyak pramuria lokalisasi Kilometer 10 yang ikut mencoblos. ΓÇ£Mari mas, kita coblos,ΓÇ¥ ajak seorang pramuria kepada wartawan fajarpapua.com yang sedang menikmati situasi pencoblosan itu. (*)</p><p>Sumber : <a href=\"https://fajarpapua.com/2024/12/07/cegah-kecurangan-psu-pilkada-mimika-328-surat-suara-sisa-tps-01-kadun-jaya-dimusnahkan-banyak-pramuria-kilo-10-ikut-coblos/\">https://fajarpapua.com/2024/12/07/cegah-kecurangan-psu-pilkada-mimika-328-surat-suara-sisa-tps-01-kadun-jaya-dimusnahkan-banyak-pramuria-kilo-10-ikut-coblos/</a></p>',1,2,5,'2025-02-11 06:28:51','2025-07-11 09:56:27'),(3,'img-berita//6870792375d05.jpeg','Dokter Juliana Galingging Luncurkan Posyandu ILP Perdana di Kampung Kadun Jaya: Akses Layanan Kesehatan Lengkap dan Terintegrasi','Timika, fajarpapua.com -Dinas Kesehatan Kabupaten Mimika melalui Puskesmas Wania bekerja sama dengan...','dokter-juliana-galingging-luncurkan-posyandu-ilp-perdana-di-kampung-kadun-jaya-akses-layanan-kesehatan-lengkap-dan-terintegrasi-2',3,'<p><strong>Timika, fajarpapua.com -</strong>Dinas Kesehatan Kabupaten Mimika melalui Puskesmas Wania bekerja sama dengan Dinas Sosial resmi meluncurkan Posyandu Integrasi Layanan Primer (ILP) perdana di Posyandu Melati, Kampung Kadun Jaya, Distrik Wania, Senin (6/5). Kegiatan ini dipimpin dokter Juliana Galingging bersama tim medis Puskesmas Wania.</p><p>Posyandu ILP merupakan pengembangan layanan kesehatan dasar yang tidak hanya menyasar balita, tetapi juga mencakup seluruh kelompok usia, mulai dari bayi usia 0 bulan hingga lanjut usia. Konsep integratif ini diharapkan mampu menjawab kebutuhan masyarakat terhadap layanan kesehatan yang menyeluruh dan mudah diakses.</p><p>ΓÇ£Ini pertama kalinya kami menerapkan model Posyandu ILP di wilayah kerja Puskesmas Wania. Kami berharap, seluruh posyandu di kampung-kampung dan kelurahan lain bisa mengikuti langkah ini,ΓÇ¥ ujar dr. Juliana Galingging kepada media di sela kegiatan.</p><p>Dalam kegiatan tersebut, Dinas Sosial turut memberikan dukungan berupa bantuan peralatan kesehatan seperti timbangan bayi dan dewasa, alat ukur tekanan darah (tensi), alat pemeriksaan gula darah, kolesterol, asam urat, hingga Hb.</p><p>ΓÇ£Bantuan dari Dinas Sosial sangat membantu. Masyarakat jadi antusias karena bisa mendapatkan pemeriksaan kesehatan yang lengkap dan gratis,ΓÇ¥ tambah dr. Juliana.</p><p>Ia juga menyampaikan harapannya agar kolaborasi lintas sektor ini dapat terus berlanjut dan ditingkatkan di masa mendatang.</p><p>ΓÇ£Kami berharap ke depannya bantuan berupa alat pemeriksaan maupun multivitamin bisa ditambah lagi, agar pelayanan yang diberikan kepada masyarakat semakin maksimal,ΓÇ¥ ungkapnya.</p><p>Peluncuran Posyandu ILP ini disambut antusias oleh masyarakat setempat yang datang memeriksakan kondisi kesehatannya. Kegiatan ini menjadi bukti nyata komitmen tenaga kesehatan, khususnya Puskesmas Wania, dalam menghadirkan layanan yang lebih inklusif dan terjangkau bagi seluruh lapisan masyarakat.(isa)</p><p>Sumber : <a href=\"https://fajarpapua.com/2025/05/08/dokter-juliana-galingging-luncurkan-posyandu-ilp-perdana-di-kampung-kadun-jaya-akses-layanan-kesehatan-lengkap-dan-terintegrasi/\">https://fajarpapua.com/2025/05/08/dokter-juliana-galingging-luncurkan-posyandu-ilp-perdana-di-kampung-kadun-jaya-akses-layanan-kesehatan-lengkap-dan-terintegrasi/</a></p>',1,2,6,'2025-02-11 06:30:02','2025-07-11 18:34:02'),(4,'img-berita/68b09fcc5b0ed.jpeg','polisi lindas ojol','polisi lindas ojol hinggal meninggal dunia&nbsp;','polisi lindas ojol',0,'<p>polisi lindas ojol hinggal meninggal dunia&nbsp;</p>',1,2,5,'2025-08-29 03:23:00','2025-08-29 03:28:29');
