INSERT INTO `sliders` VALUES (1,'Selamat Datang di Kampung Kadun Jaya','Portal informasi resmi Kampung Kadun Jaya, Distrik Wania, Kabupaten Mimika. Temukan berbagai informasi layanan, berita, dan kegiatan kampung kami.','img-slider//687074b49e2da.jpg','#','2025-02-11 03:21:45','2025-08-23 14:57:00'),(2,'Sejarah Kampung Kadun Jaya','Kampung Kadun Jaya memiliki sejarah panjang sebagai bagian dari Distrik Wania, Kabupaten Mimika. Kampung ini terus berkembang dengan mempertahankan nilai-nilai budaya dan tradisi Papua yang kaya.','img-slider//67aacc68000d2.png','#','2025-02-11 03:21:45','2025-08-23 14:57:00'),(3,'Visi & Misi Kampung','Visi: Terwujudnya Kampung Kadun Jaya yang Maju, Sejahtera, Bersih, dan Religius. Misi: Meningkatkan pelayanan kepada masyarakat, pemberdayaan ekonomi, dan pelestarian budaya Papua.','img-slider//67aaca21bd8df.jpeg','#','2025-02-11 03:21:45','2025-08-23 14:57:00');
/*!40000 ALTER TABLE `sliders` ENABLE KEYS */;
