INSERT INTO `visi_misis` VALUES (1,'Terwujudnya Kampung Kadun Jaya yang sejahtera, mandiri, dan berbudaya','- Meningkatkan perekonomian masyarakat melalui pengembangan potensi pertanian, perkebunan, dan pariwisata\r\n                            - Meningkatkan kualitas sumber daya manusia melalui pendidikan dan kesehatan\r\n                            - Meningkatkan kesadaran masyarakat akan pentingnya kelestarian lingkungan',1,'2025-02-11 03:21:45','2025-07-11 09:59:30');
